'use client';
import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
type Item = { _id: string; itemName: string; category: string; description: string; status: string; price: number; location: string; isActive: boolean; images?: string[] };
export default function MyItems() {
  const [items, I] = useState<Item[]>([]), [error, E] = useState(''), [editing, setEditing] = useState<Item | null>(null), [viewing, setViewing] = useState<Item | null>(null), [busy, B] = useState(false);
  async function load() { try { I(await api<Item[]>('/menu/vendor/mine')); E(''); } catch (e: any) { E(e.message); } }
  useEffect(() => { load(); }, []);
  async function remove(id: string) { if (!window.confirm('Delete this menu item?')) return; try { await api(`/menu/${id}`, { method: 'DELETE' }); toast.success('Menu item deleted'); load(); } catch (e: any) { toast.error(e.message); } }
  async function availability(item: Item) { try { await api(`/menu/${item._id}`, { method: 'PATCH', body: JSON.stringify({ isActive: !item.isActive }) }); toast.success(item.isActive ? 'Item made unavailable' : 'Item made available'); load(); } catch (e: any) { toast.error(e.message); } }
  async function save(e: React.FormEvent) { e.preventDefault(); if (!editing) return; B(true); try { await api(`/menu/${editing._id}`, { method: 'PATCH', body: JSON.stringify({ itemName: editing.itemName, description: editing.description, price: Number(editing.price), location: editing.location }) }); toast.success('Changes saved. Updated item is pending admin review.'); setEditing(null); load(); } catch (e: any) { toast.error(e.message); } finally { B(false); } }
  return <main className="section"><p className="hero-kicker">YOUR RESTAURANT CATALOG</p><h1>My Menu Items</h1><p className="muted">View approval status, edit item details, and manage availability.</p>{error && <div className="empty-state">{error}</div>}{!items.length && !error ? <div className="empty-state">No menu items yet. Add your first item to get started.</div> : <div className="grid">{items.map(x => <article className="card item-card" key={x._id}>{x.images?.[0] ? <img className="menu-image" src={x.images[0]} alt={x.itemName} /> : <div className="menu-image" style={{ display: 'grid', placeItems: 'center', fontSize: 65 }}>🍕</div>}<h3>{x.itemName}</h3><p className="muted">{x.category} · {x.location}</p><strong>৳{x.price}</strong><p><span className={`status-pill status-${x.status}`}>{x.status}</span> <span className="status-pill">{x.isActive ? 'Available' : 'Unavailable'}</span></p><div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}><button className="btn secondary" onClick={() => setViewing(x)}>View Details</button><button className="btn" onClick={() => setEditing(x)}>Edit</button><button className="btn secondary" onClick={() => availability(x)}>{x.isActive ? 'Set Unavailable' : 'Set Available'}</button><button className="btn secondary" onClick={() => remove(x._id)}>Delete</button></div></article>)}</div>}
    {viewing && <div className="modal-backdrop"><div className="card edit-modal"><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><h2>Menu Item Details</h2><button type="button" className="btn secondary" onClick={() => setViewing(null)}>Close</button></div>{viewing.images?.map(src => <img key={src} src={src} alt={viewing.itemName} className="menu-image" />)}<h3>{viewing.itemName}</h3><p className="muted">{viewing.category} · {viewing.location}</p><strong>৳{viewing.price}</strong><p>{viewing.description}</p><p><span className={`status-pill status-${viewing.status}`}>{viewing.status}</span> <span className="status-pill">{viewing.isActive ? 'Available' : 'Unavailable'}</span></p></div></div>}
    {editing && <div className="modal-backdrop"><form className="card edit-modal" onSubmit={save}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><h2>Edit Menu Item</h2><button type="button" className="btn secondary" onClick={() => setEditing(null)}>Close</button></div><label>Item Name<input required value={editing.itemName} onChange={e => setEditing({ ...editing, itemName: e.target.value })} /></label><label>Description<textarea required minLength={10} value={editing.description} onChange={e => setEditing({ ...editing, description: e.target.value })} /></label><label>Price<input type="number" min="1" required value={editing.price} onChange={e => setEditing({ ...editing, price: Number(e.target.value) })} /></label><label>Location<input required value={editing.location} onChange={e => setEditing({ ...editing, location: e.target.value })} /></label><button className="btn" disabled={busy}>{busy ? 'Saving…' : 'Save Changes'}</button><p className="muted">Editing an approved item sends it back to Pending review.</p></form></div>}
  </main>;
}
